import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// Local authority adapter: no secrets, credentials or network are accessed.
console.error('EXTERNAL_AUTHORITY_REQUIRED: publishing account authorization is absent; request operator authorization, never fabricate it');
process.exit(78);

// @file: Approved normal and invalid-input scenarios for selectBatch.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { selectBatch } from './queue.ts';

describe('selectBatch', () => {
  it('[COR-REQ-1] public behavior', () => {
    // contract: ordered prefix with duplicates preserved, fresh result, caller array untouched
    const values = ['first', 'first', 'third', 'fourth'];
    const result = selectBatch(values, 2);

    assert.deepStrictEqual(result, ['first', 'first']);
    assert.notStrictEqual(result, values);
    assert.deepStrictEqual(values, ['first', 'first', 'third', 'fourth']);
    assert.deepStrictEqual(selectBatch(values, 0), []);
    assert.deepStrictEqual(selectBatch(values, values.length), [...values]);
  });

  it('[COR-REQ-2] invalid input', () => {
    // contract: every invalid runtime input raises TypeError without mutating the caller's array
    const values = ['first'];

    assert.throws(() => selectBatch('not-an-array' as unknown as string[], 1), TypeError);
    assert.throws(() => selectBatch(['first', 2 as unknown as string], 1), TypeError);
    assert.throws(() => selectBatch(values, -1), TypeError);
    assert.throws(() => selectBatch(values, 1.5), TypeError);
    assert.throws(() => selectBatch(values, Number.NaN), TypeError);
    assert.throws(() => selectBatch(values, Number.POSITIVE_INFINITY), TypeError);
    assert.throws(() => selectBatch(values, Number.NEGATIVE_INFINITY), TypeError);
    assert.deepStrictEqual(values, ['first']);
  });
});

// @file: Pure selectBatch implementation.
// @spec: COR
// @consumers: src/queue.test.ts
/** @purpose Select a validated queue prefix. | @param values Original jobs. | @param capacity Maximum jobs. | @returns Fresh ordered prefix. | @throws TypeError for invalid input. */
export function selectBatch(values: readonly string[], capacity: number): string[] {
  if (!Array.isArray(values) || values.some(v => typeof v !== 'string') || !Number.isInteger(capacity) || capacity < 0) throw new TypeError('invalid queue input');
  return values.slice(0, capacity);
}
